let geo=null,geoMessage='',leafMap=null,mapCenter=[1.347,103.839],mapZoom=11,mapBoundFilter=false,authStep=0,signupDraft={name:'',email:'',phone:'',interests:[],gender:'Prefer not to say',age:'Prefer not to say'},storyIndex=0,storyTimer=null,selectedBusinessId=1;
state.profile.phone??='';state.isBusiness??=false;state.knowledge??=[{id:1,question:'How do chain rewards work?',answer:'A customer pays full price on their first visit. Every next different business in the chain gives $1 off. There is no percentage cashback.'},{id:2,question:'When can customers collect an order?',answer:'Sunday Bakehouse demo pickups are from 10am to 5pm. Book an appointment in the calendar to reserve a time.'}];state.chats??=[];state.orders??=[];state.motion??=true;if(!state.designVersion){state.business.accent='#2d6650';state.visits.forEach(v=>{if(v.discount>1){v.amount+=v.discount-1;v.discount=1}});state.designVersion=2;persist();}
if(matchMedia('(prefers-reduced-motion: reduce)').matches)state.motion=false;
let logo=(light=false)=>`<a class="grove-logo ${light?'light':''}" href="#/landing" aria-label="The Grove homepage"><span class="logo-g">g<span class="logo-dot"></span></span><span>the grove<span class="logo-period">.</span></span></a>`;
let mascot=(cls='')=>`<img class="mascot ${cls}" src="assets/grove-mascot.png" alt="Grove, our friendly green sprout mascot, waving hello" onerror="this.style.visibility='hidden'">`;
const localDate=()=>new Date().toLocaleDateString('en-CA');
const nextReward=()=>state.chain.length>0&&state.chain.length<4?1:0;
const cashSaved=()=>state.visits.reduce((s,v)=>s+v.discount,0);
function landing(){return `<div class="landing"><header class="landing-nav">${logo()}<nav aria-label="About The Grove"><a href="#about" data-section="about">Our story</a><a href="#how" data-section="how">How it works</a><a href="#community" data-section="community">The community</a></nav><a class="btn landing-login" href="#/login">Log in</a></header><main><section class="landing-hero"><div class="hero-text"><div class="eyebrow"><span class="tiny-star">✦</span> LITTLE FINDS. BIG CONNECTIONS.</div><h1>Your next<br>favourite is<br><em>closer than<br>you think.</em></h1><p>A little curiosity goes a long way. Find your people, discover something different, and grow your own local chain.</p><a href="#/customer/discover" class="btn coral">Explore businesses ${icon('compass')}</a><button class="story-link" data-new="story"><span class="play-circle">▶</span> Meet Grove in 20 seconds</button></div><div class="hero-stage"><div class="stage-orbit orbit-one"></div><div class="stage-orbit orbit-two"></div><span class="stage-label label-top">your local discovery buddy</span><div class="mascot-halo"></div>${mascot('hero-mascot')}<span class="floating-tag tag-one">✦ a little more curious</span><span class="floating-tag tag-two">♡ a little more connected</span><div class="meet-label"><span>Hello, I’m</span><strong>Grove!</strong><span class="hand-drawn">small sprout. big heart.</span></div><button class="motion-switch" data-new="motion" aria-pressed="${state.motion}">${state.motion?'Ⅱ Pause':'▶ Play'} motion</button></div></section><div class="brand-ribbon" aria-label="Made for curious people"><span>NEARBY FINDS</span><i>✦</i><span>REAL CONNECTIONS</span><i>✦</i><span>SMALL BUSINESS LOVE</span><i>✦</i><span>GOOD THINGS GROW HERE</span></div><section id="about" class="landing-section about-section"><div><div class="eyebrow">SO, WHAT’S THE GROVE?</div><h2>More than a place.<br><em>A feeling of belonging.</em></h2></div><div class="about-copy"><p>That Saturday plan you didn’t know you needed. A handmade gift with a story. The maker around the corner who remembers your name.</p><p>The Grove connects Singapore’s curious locals with independent home businesses. We help good discoveries lead to the next—and give small businesses the space to grow.</p><div class="mission"><span>OUR MISSION</span><strong>Make local discovery rewarding.<br>Make small business feel supported.</strong></div></div></section><section id="how" class="landing-section how-section"><div class="section-kicker"><span class="eyebrow">A LITTLE CHAIN REACTION</span><span class="pill">Every next stop, $1 off</span></div><h2>One good thing<br><em>leads to another.</em></h2><div class="how-grid"><article><span class="big-step">01</span><h3>Find your kind of thing.</h3><p>Tell us what you love. Explore nearby businesses and make your first discovery.</p><span class="step-label">CURIOUS? GOOD.</span></article><article><span class="big-step">02</span><h3>Make a little connection.</h3><p>Visit a participating business. Your first visit starts your local chain.</p><span class="step-label">FIRST VISIT · FULL PRICE</span></article><article><span class="big-step">03</span><h3>Keep the good going.</h3><p>Visit a different business in your chain and enjoy $1 off. Another next stop? Another $1 off.</p><span class="step-label">NEXT VISIT · $1 OFF</span></article></div></section><section id="community" class="landing-section community-section"><div class="section-title"><div><div class="eyebrow">NOT YOUR USUAL SCROLL</div><h2>A world of little passions.</h2></div><p>For your weekends, your creative streak,<br>and your “let’s try something new” days.</p></div><div class="passion-grid">${[['Bakes & bites','Good mornings, made by hand.','bread'],['Art & craft','Less scrolling. More making.','pottery'],['Flowers & plants','A little joy to take home.','flowers']].map(([c,t,im],i)=>`<a class="passion-card passion-${i}" href="#/customer/discover" data-discover-category="${c}"><img src="${imgs[im]}" alt="${c}" loading="lazy"><div><span>0${i+1} / YOUR NEXT DISCOVERY</span><h3>${c}</h3><p>${t}</p></div></a>`).join('')}</div></section><section class="mascot-story landing-section"><div class="mascot-mini-stage">${mascot('story-mascot')}<span class="scribble-note">your biggest little supporter</span></div><div><div class="eyebrow">MEET YOUR NEIGHBOURHOOD OPTIMIST</div><h2>Small sprout.<br><em>Very big heart.</em></h2><p>Grove believes the best things grow when we grow together. Part curious explorer, part enthusiastic cheerleader—always ready to nudge you towards something wonderful.</p><p>The two leaves? Curiosity and connection. The little orange bag? There’s always room for a new discovery.</p><button class="btn secondary" data-new="story">Watch Grove’s little story</button></div></section><section class="landing-section makers-section"><div><div class="eyebrow">FOR THE PEOPLE WHO MAKE IT HAPPEN</div><h2>You bring the passion.<br>We’ll bring a little support.</h2><p>Get discovered by curious new customers. Know what they love. Keep orders, money, and your schedule in one place—so you have more time for your craft.</p><a class="underlink" href="#/customer/settings">Explore business registration</a></div><div class="maker-features"><div><span>01</span><h3>Be part of someone’s next discovery.</h3><p>Connect with customers through neighbouring businesses.</p></div><div><span>02</span><h3>Understand what brings them back.</h3><p>See customer interests, favourite products, and emerging patterns.</p></div><div><span>03</span><h3>Keep the everyday simple.</h3><p>A calmer home for orders, appointments, and finances.</p></div></div></section><section class="landing-section faq-section"><div><div class="eyebrow">A FEW THINGS YOU MIGHT BE WONDERING</div><h2>Good questions.<br>Simple answers.</h2></div><div>${[['Who is The Grove for?','Curious Singapore locals who want to discover independent businesses, and home-business owners who want to grow and manage their work.'],['How much do I save in a chain?','Your first business starts the chain. Each next different participating business gives $1 off. Four visits mean up to $3 saved in total.'],['Do I have to share my location?','Location access helps sort nearby finds. You choose whether to allow it in your browser; you can still explore the map or choose a region without it.'],['Can I try this without a real account?','Yes. This is an NTU DIP frontend prototype. Demo sign-in, orders, rewards, analytics, and chats are stored in your browser, with no real payments or messages sent.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="closing-note"><span>✦</span><p>A little local love<br>goes a <em>long way.</em></p><span>✦</span></section></main><footer class="landing-footer">${logo()}<p>Good things grow together.<br><small>NTU DIP · The Grove · Frontend prototype</small></p><div><a href="#/login">Log in</a><a href="#/signup">Join the community</a><button class="text-btn" data-new="motion">${state.motion?'Pause':'Enable'} animations</button></div></footer></div>`}
function authPage(){const signup=route==='signup';return `<main class="auth-page"><aside class="auth-art">${logo(true)}<div><div class="eyebrow">MAKE ROOM FOR A LITTLE DISCOVERY</div><h1>Your people.<br>Your passions.<br><em>Your Grove.</em></h1>${mascot('auth-mascot')}<p>Good things grow together.</p></div><span>Made for curious locals in Singapore.</span></aside><section class="auth-content"><a class="auth-back" href="#/landing">‹ Back to The Grove</a><div class="auth-card">${signup?signupForm():`<div class="eyebrow">WELCOME BACK, NEIGHBOUR</div><h2>A little more local.<br>A lot more you.</h2><p>Step into your Grove.</p><form id="login-v2">${field('Email address','email',state.profile.email,'email')}<p class="muted">A demo account is ready for you. No password needed.</p><button class="btn full">Log in to demo</button></form><p class="auth-signup"><a href="#/signup">Sign up as a customer</a></p><div class="auth-footnote">Frontend demo · Your changes stay in this browser.</div>`}</div></section></main>`}
function signupForm(){if(authStep===0)return `<div class="eyebrow">A NEW LITTLE BEGINNING · 1 OF 2</div><h2>Nice to meet you.</h2><p>Let’s make this your kind of place.</p><form id="signup-details">${field('Your name','name',signupDraft.name)}${field('Email address','email',signupDraft.email,'email')}${field('Phone number','phone',signupDraft.phone,'tel')}<button class="btn full">Choose my interests</button></form><p class="auth-signup">Already exploring? <a href="#/login">Log in</a></p>`;return `<div class="eyebrow">YOUR KIND OF GOOD · 2 OF 2</div><h2>What sparks your curiosity?</h2><p>Choose one or more. You can change these later.</p><div class="interest-grid">${interests.map((c,i)=>`<button class="interest-tile ${signupDraft.interests.includes(c)?'chosen':''}" data-new="signup-interest" data-value="${c}" aria-pressed="${signupDraft.interests.includes(c)}"><span>${['◒','◈','✿','☀','✧','◡'][i]}</span>${c}<b>${signupDraft.interests.includes(c)?'✓':'+'}</b></button>`).join('')}</div><form id="signup-finish"><details class="optional-details"><summary>Optional: help us understand our community</summary><p class="subtle">You can skip these. Demo insights use synthetic data, not these answers.</p><div class="form-grid"><div class="field"><label for="gender">Gender</label><select id="gender" name="gender">${['Prefer not to say','Woman','Man','Non-binary','Self-described'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="age">Age range</label><select id="age" name="age">${['Prefer not to say','Under 18','18–24','25–34','35–44','45+'].map(x=>`<option>${x}</option>`).join('')}</select></div></div></details><button class="btn full" ${!signupDraft.interests.length?'disabled':''}>Create demo account</button><button type="button" class="text-btn full" data-new="signup-back">Back</button></form>`}
customerNav.push(['settings','edit','Settings']);ownerNav.splice(3,0,['insights','compass','Insights']);ownerNav.push(['business','chain','Business & QR'],['assistant','leaf','Grove assistant']);
shell=function(){document.body.classList.toggle('motion-paused',!state.motion);if(['landing','login','signup'].includes(route)){$('#app').innerHTML=route==='landing'?landing():authPage();return}const nav=mode==='owner'?ownerNav:customerNav;$('#app').innerHTML=`<div class="app-shell ${mode}-shell"><aside class="sidebar">${logo()}<span class="sidebar-caption">${mode==='owner'?'BUSINESS STUDIO':'YOUR LITTLE CORNER'}</span><nav class="nav" aria-label="Main navigation">${nav.map(([r,i,t])=>`<a href="#/${mode}/${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="side-card">${mascot('side-mascot')}<h3>Good things grow together.</h3><a href="#/landing" class="text-btn">Meet The Grove</a></div><div class="side-user"><span class="avatar">${esc(state.profile.name.slice(0,1))}</span><div><strong>${mode==='owner'?esc(state.business.name):esc(state.profile.name)}</strong><small>${mode==='owner'?'Business owner':'Curious local'}</small></div></div>${state.isBusiness?`<a class="switch-workspace" href="#/${mode==='owner'?'customer/home':'owner/dashboard'}">${mode==='owner'?'Customer view':'Open business studio'}</a>`:''}</aside><main class="main">${mode==='owner'?`<header class="topbar"><span class="studio-label">${icon('leaf')} THE GROVE <b>BUSINESS STUDIO</b></span><div><button class="btn secondary small" data-new="store-preview">Preview storefront</button><span class="pill">Demo workspace</span></div></header>`:''}<div id="content" class="content page-enter"></div></main></div>`;renderPage()};
handleRoute=function(){if(leafMap){leafMap.remove();leafMap=null}clearInterval(storyTimer);const parts=location.hash.replace(/^#\/?/,'').split('/');if(!parts[0]||['landing','login','signup'].includes(parts[0])){route=parts[0]||'landing';mode='customer'}else{mode=parts[0]==='owner'?'owner':'customer';const allowed=(mode==='owner'?ownerNav:customerNav).map(n=>n[0]);allowed.push('store');route=allowed.includes(parts[1])?parts[1]:allowed[0];if(route==='store')selectedBusinessId=Number(parts[2])||1}query='';shell();window.scrollTo(0,0)};
window.addEventListener('hashchange',handleRoute);

function distanceTo(id){if(!geo)return null;const [lat,lon]=coordinates[id],rad=Math.PI/180,dlat=(lat-geo.lat)*rad,dlon=(lon-geo.lon)*rad,a=Math.sin(dlat/2)**2+Math.cos(geo.lat*rad)*Math.cos(lat*rad)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))}
function proximity(id){const d=distanceTo(id);return d===null?business(id).area:`${d.toFixed(1)} km away`}
const baseFiltered=filtered;
filtered=function(){let list=baseFiltered();return list.sort((a,b)=>{const interest=state.profile.recommendations?(Number(state.profile.interests.includes(b.category))-Number(state.profile.interests.includes(a.category))):0;return interest||(geo?distanceTo(a.id)-distanceTo(b.id):a.distance-b.distance)})};
const baseCard=card;
card=function(b){return `<article class="discovery-card"><div class="discovery-image"><button class="image-open" data-new="open-store" data-id="${b.id}" aria-label="Explore ${esc(b.name)}"><img src="${imgs[b.image]}" alt="${esc(b.category)}" loading="lazy"></button><span class="card-category">${esc(b.category)}</span><button class="save ${state.saved.includes(b.id)?'saved':''}" data-action="save" data-id="${b.id}" aria-label="${state.saved.includes(b.id)?'Unsave':'Save'} ${esc(b.name)}" aria-pressed="${state.saved.includes(b.id)}">${icon('heart')}</button></div><div class="discovery-body"><span class="maker-line">MADE WITH HEART BY ${esc(b.owner.toUpperCase())}</span><h3><button data-new="open-store" data-id="${b.id}">${esc(b.name)}</button></h3><p>${esc(b.tag)}</p><div class="discovery-meta"><span>★ ${b.rating} · ${esc(proximity(b.id))}</span><strong>From ${money(b.menu[0][1])}</strong></div><button class="explore-store" data-new="open-store" data-id="${b.id}">Step inside ${icon('compass')}</button></div></article>`};
chainBanner=function(){return `<section class="local-chain-strip"><div><span class="chain-symbol">${icon('chain')}</span><div><span class="eyebrow">YOUR LOCAL CHAIN</span><h3>${state.chain.length>=4?'Four stops. One happy little chain.':state.chain.length?'Keep a good thing growing.':'Your first discovery starts here.'}</h3></div></div><div class="chain-mini-reward"><strong>${money(cashSaved())}</strong><span>total saved</span></div><div class="chain-mini-reward"><strong>${money(nextReward())}</strong><span>next visit reward</span></div><a href="#/customer/chain" class="btn secondary small">View chain</a></section>`};
home=function(){let list=filtered(),n=recOffset%Math.max(list.length,1);list=[...list.slice(n),...list.slice(0,n)];return heading(`Hey ${esc(state.profile.name.split(' ')[0])},<br>what’s your kind of good?`,'Something handmade. Something unexpected. Something just for you.')+chainBanner()+searchBox()+`<div class="discovery-intro"><div><span class="eyebrow">A LITTLE CURIOSITY LOOKS GOOD ON YOU</span><h2>New places.<br>Same neighbourhood.</h2><p>There’s a whole world of little passions nearby.</p><a class="btn soft" href="#/customer/discover">Explore the map</a></div>${mascot('discovery-mascot')}</div><div class="section-title"><div><h2>${state.profile.recommendations?'Picked for your interests':'Explore the community'}</h2><p>${state.profile.recommendations?esc(state.profile.interests.join(' · ')):'Browse all of our demo businesses.'}</p></div><button class="text-btn" data-action="refresh">${icon('refresh')} Fresh picks</button></div>${chips()}<div class="cards">${list.slice(0,6).map(card).join('')||'<div class="empty">No matching businesses yet. Try All discoveries or another search.</div>'}</div>`};
discover=function(){const list=filtered();return heading('Let curiosity lead the way.','Pan, zoom, and find your next stop.')+chainBanner()+searchBox()+chips()+`<div class="map-toolbar"><select id="region-filter" aria-label="Filter by region">${['All','North','South','East','West'].map(r=>`<option value="${r}" ${r===region?'selected':''}>${r==='All'?'All regions':r+' Singapore'}</option>`).join('')}</select><button class="btn secondary small" data-new="locate">${icon('pin')} ${geo?'Refresh my location':'Use my location'}</button><button class="text-btn" data-new="map-reset">Show all locations</button></div><p id="geo-status" class="muted" role="status">${esc(geoMessage||'Location is optional. Allow it to sort nearby demo businesses; or explore a region yourself.')}</p><div class="real-map-layout"><div class="map-result-column"><div class="section-title"><h3 id="map-result-count">${list.length} local discoveries</h3><span class="demo-tag">SAMPLE LISTINGS</span></div><div id="map-results">${mapResults(list)}</div></div><div class="map-wrapper"><div id="leaflet-map" tabindex="0" aria-label="Interactive map of Singapore. Drag to move, use plus and minus to zoom."></div><button class="search-area btn small" data-new="search-area">Search this map area</button><div id="map-load-note" class="map-load-note">Sample business locations · OpenStreetMap</div></div></div>`};
function mapResults(list){return list.map(b=>`<div class="map-result"><button data-new="focus-pin" data-id="${b.id}" class="map-result-photo" aria-label="Show ${esc(b.name)} on map"><img src="${imgs[b.image]}" alt="${esc(b.category)}"></button><div><span class="muted">${esc(b.category)}</span><h3><button data-new="open-store" data-id="${b.id}">${esc(b.name)}</button></h3><p>${esc(proximity(b.id))} · ★ ${b.rating}</p><button class="text-btn" data-new="focus-pin" data-id="${b.id}">Locate on map</button></div></div>`).join('')||'<div class="empty">No businesses in this area. Zoom out or change your filters.</div>'}
function initMap(){if(!$('#leaflet-map'))return;if(!window.L){$('#leaflet-map').innerHTML='<div class="empty">The map could not load. Browse the businesses beside it.</div>';return}if(leafMap){leafMap.remove();leafMap=null}leafMap=L.map('leaflet-map',{scrollWheelZoom:false}).setView(mapCenter,mapZoom);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a>'}).on('tileerror',()=>{if($('#map-load-note'))$('#map-load-note').textContent='Map tiles unavailable. Markers and business list remain usable.'}).addTo(leafMap);filtered().forEach(b=>L.marker(coordinates[b.id],{icon:L.divIcon({className:'grove-map-pin',html:`<span>${b.id}</span>`,iconSize:[34,40],iconAnchor:[17,40]})}).addTo(leafMap).bindPopup(`<div class="map-popup"><strong>${esc(b.name)}</strong><p>${esc(b.category)} · ${esc(b.area)}</p><button class="btn small" data-new="open-store" data-id="${b.id}">View business</button></div>`));if(geo)L.circleMarker([geo.lat,geo.lon],{radius:8,color:'#fff',weight:3,fillColor:'#398af2',fillOpacity:1}).addTo(leafMap).bindPopup('Your approximate location');leafMap.on('moveend',()=>{const c=leafMap.getCenter();mapCenter=[c.lat,c.lng];mapZoom=leafMap.getZoom()});leafMap.invalidateSize()}
function locateUser(){if(!navigator.geolocation){geoMessage='Location is unavailable in this browser. Choose a region instead.';toast(geoMessage);return}geoMessage='Waiting for location permission…';if($('#geo-status'))$('#geo-status').textContent=geoMessage;navigator.geolocation.getCurrentPosition(pos=>{geo={lat:pos.coords.latitude,lon:pos.coords.longitude};mapCenter=[geo.lat,geo.lon];mapZoom=13;geoMessage='Location enabled for this session. Distances use approximate demo business locations.';if(route==='discover'||route==='home')renderPage();toast('Location enabled. Your nearby recommendations are ready.')},err=>{geoMessage=err.code===1?'Location permission was declined. You can still search the map or choose a region.':'We couldn’t get your location. Try again or choose a region.';if($('#geo-status'))$('#geo-status').textContent=geoMessage;toast(geoMessage)},{enableHighAccuracy:false,timeout:12000,maximumAge:60000})}
chain=function(){return heading('Good things come in chains.','First stop: full price. Every next different business: $1 off.')+`<div class="reward-summary"><div><span class="eyebrow">YOUR CHAIN REWARDS</span><strong>${money(cashSaved())}</strong><p>Total cash saved · discounts already applied</p></div><div><span class="eyebrow">NEXT VISIT</span><strong>${money(nextReward())}<small> off</small></strong><p>${state.chain.length>=4?'Chain complete. Start a new one.':state.chain.length?'At your next different business.':'Make your first visit to unlock $1 off.'}</p></div>${mascot('reward-mascot')}</div><section class="panel"><div class="section-title" style="margin-top:0"><h2>Your local chain</h2><span class="pill">${state.chain.length} of 4 visits</span></div><div class="chain-track">${[0,1,2,3].map(i=>{const b=state.chain[i]?business(state.chain[i]):null;return `<div class="chain-node ${b?'completed':''}"><span>${b?'✓':i+1}</span><h3>${b?esc(b.name):i===state.chain.length?'Next discovery':'Next stop'}</h3><p>${i===0?'Full price':'$1 off'}</p></div>`}).join('')}</div>${state.chain.length>=4?'<button class="btn" data-action="new-chain">Start a new chain</button>':''}</section>${state.chain.length<4?`<div class="section-title"><h2>Your next chapter</h2><span class="muted">A different business. Another little reward.</span></div><div class="cards">${businesses.filter(b=>!state.chain.includes(b.id)).slice(0,3).map(b=>card(business(b.id))).join('')}</div>`:''}`};
profile=function(){return heading('Your little corner of The Grove.','A few favourites, a little progress, a lot to look forward to.')+`<section class="profile-hero"><span class="profile-avatar">${esc(state.profile.name.split(' ').map(n=>n[0]).join('').slice(0,2))}</span><div><div class="eyebrow">CURIOUS LOCAL</div><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.email)}</p><div class="categories">${state.profile.interests.map(c=>`<span class="pill">${esc(c)}</span>`).join('')}</div></div>${mascot('profile-mascot')}</section><div class="stats">${stat('Chain rewards',money(cashSaved()),'Cash saved')}${stat('Next visit reward',money(nextReward()),'At a different business')}${stat('Local visits',state.visits.length,'Little connections')}${stat('Saved favourites',state.saved.length,'Your next plans')}</div><div class="section-title"><h2>Saved for another day</h2></div><div class="cards">${state.saved.map(id=>card(business(id))).join('')||'<div class="empty">Tap a heart on a business to save it here.</div>'}</div><section class="panel" style="margin-top:24px"><h2>Your demo bookings</h2>${state.appointments.filter(a=>a.name===state.profile.name).map(a=>`<div class="list-row"><div><strong>${esc(a.businessName||state.business.name)}</strong><p>${esc(a.service)} · ${date(a.date)} · ${a.time}</p></div><span class="pill">${a.status}</span></div>`).join('')||'<p class="muted">Your next adventure is waiting.</p>'}</section>`};
function settings(){return heading('Make The Grove yours.','Your details and preferences, all in one place.')+`<div class="grid2"><form class="panel" id="settings-v2"><h2>Your details</h2>${field('Name','name',state.profile.name)}${field('Email address','email',state.profile.email,'email')}${field('Phone number','phone',state.profile.phone,'tel')}<button class="btn">Save changes</button></form><section class="panel"><h2>Your interests</h2><div class="categories">${interests.map(c=>`<button class="chip ${state.profile.interests.includes(c)?'active':''}" data-action="interest" data-category="${c}" aria-pressed="${state.profile.interests.includes(c)}">${c}</button>`).join('')}</div><label class="toggle-row"><span>Personalised recommendations</span><input type="checkbox" data-setting="recommendations" ${state.profile.recommendations?'checked':''}></label><label class="toggle-row"><span>Demo appointment reminders</span><input type="checkbox" data-setting="reminders" ${state.profile.reminders?'checked':''}></label><label class="toggle-row"><span>Playful animations</span><input type="checkbox" id="motion-setting" ${state.motion?'checked':''}></label><p class="subtle">Location is only requested when you press “Use my location” in Discover. It is not saved with your profile.</p></section></div><section class="business-invite"><div><h2>${state.isBusiness?'Your business is part of The Grove.':'Got a little business with a big heart?'}</h2><p>${state.isBusiness?'Your studio is ready whenever you are.':'Make your craft someone’s next discovery.'}</p></div><a class="btn" href="#/owner/${state.isBusiness?'dashboard':'business'}">${state.isBusiness?'Open business studio':'Sign up as business'}</a></section>`}
function storefrontMarkup(id,preview=false){const b=business(id);return `<div class="storefront"><div class="store-hero" style="background:${id===1&&/^#[0-9a-f]{6}$/i.test(b.accent)?b.accent:'#36694e'}"><div><span class="eyebrow">${esc(b.category)} · ${esc(b.area)}</span><h1>${esc(b.name)}<span>.</span></h1><p>${esc(b.description)}</p><div class="store-meta"><span>Made by ${esc(b.owner)}</span><span>★ ${b.rating} · ${b.reviews} reviews</span></div>${preview?'<span class="pill">Customer preview · no bookings or visits recorded</span>':`<div class="modal-actions"><button class="btn soft" data-action="book" data-id="${id}">Book a visit</button><button class="btn secondary" data-action="save" data-id="${id}">${state.saved.includes(id)?'Saved to favourites':'Save to favourites'}</button></div>`}</div><img src="${imgs[b.image]}" alt="${esc(b.category)} from ${esc(b.name)}"></div><div class="store-body"><div class="section-title"><div><div class="eyebrow">A LITTLE SOMETHING, MADE FOR YOU</div><h2>The menu</h2></div><span class="pill">Small batches · Personal touches</span></div><div class="product-grid">${b.menu.map((m,i)=>`<article class="product-card"><span class="product-number">0${i+1}</span><h3>${esc(m[0])}</h3><p>${['Made with care. Best enjoyed slowly.','A little favourite, from our hands to yours.','A special treat for an ordinary day.'][i%3]}</p><strong>${money(m[1])}</strong>${!preview?`<button class="text-btn" data-action="book" data-id="${id}">Enquire & book</button>`:''}</article>`).join('')}</div><div class="store-bottom"><div><h3>A note from ${esc(b.owner.split(' ')[0])}</h3><p>Thank you for supporting a small local dream. Every order means a little more than you know.</p>${id===1?`<p class="muted">${esc(b.phone)}<br>${esc(b.email)}</p><a class="underlink" href="${safeUrl(b.website)}" target="_blank" rel="noopener noreferrer">Purchase website</a>`:''}</div>${!preview?`<div class="store-chain"><span class="eyebrow">ONE GOOD THING LEADS TO ANOTHER</span><h3>${state.chain.includes(id)?'Already part of your story.':state.chain.length>=4?'Your chain is complete.':state.chain.length?'Your next visit gives you $1 off.':'Start your local chain here.'}</h3>${!state.chain.includes(id)&&state.chain.length<4?`<button class="btn" data-new="confirm-visit" data-id="${id}">Confirm demo visit</button>`:'<a class="btn secondary" href="#/customer/chain">View chain</a>'}<p class="subtle">Demo only. No purchase is made.</p></div>`:''}</div></div></div>`}
function storePage(){return `<a class="back-link" href="#/customer/discover">‹ Back to discoveries</a>`+storefrontMarkup(selectedBusinessId)}
detail=function(id){selectedBusinessId=id;if(mode==='owner'){previewStore();return}location.hash=`/customer/store/${id}`};
function previewStore(){showModal(`<div class="preview-heading"><span class="pill">STOREFRONT PREVIEW</span><p>You’re still in your business workspace.</p></div>${storefrontMarkup(1,true)}`);$('#modal').classList.add('wide-modal')}
const originalShowModal=showModal;showModal=function(html){$('#modal').classList.remove('wide-modal');originalShowModal(html)};
function confirmVisit(id){if(state.chain.includes(id)||state.chain.length>=4)return;const b=business(id),reward=state.chain.length?1:0;state.chain.push(id);state.visits.unshift({business:id,date:localDate(),amount:Math.max(0,b.menu[0][1]-reward),discount:reward});persist();if($('#modal').open)$('#modal').close();go('chain');toast(reward?'Visit confirmed · $1 saved!':'Your first visit is in. Your next stop gets $1 off.');celebrate()}
function celebrate(){const layer=document.createElement('div');layer.className='celebration';layer.setAttribute('aria-hidden','true');layer.innerHTML=Array.from({length:16},(_,i)=>`<i style="--n:${i};--c:${['#e99b6a','#98ba71','#2d6650'][i%3]}"></i>`).join('');document.body.append(layer);setTimeout(()=>layer.remove(),1400)}
let insightDays=30;
const demoAudience=Array.from({length:80},(_,i)=>({id:i+1,gender:i<51?'Women':i<73?'Men':i<77?'Non-binary':'Not shared',age:i<24?'18–24':i<62?'25–34':i<74?'35–44':'45+',preference:interests[i%5===0?1:i%7===0?2:0]}));
const demoProductOrders=Array.from({length:160},(_,i)=>({customer:(i*13)%80+1,daysAgo:i%60,product:i%4<2?'Brown butter cookies':i%4===2?'Weekend pastry box':'Signature sourdough',units:1+i%3}));
function analyticsData(){const current=demoProductOrders.filter(o=>o.daysAgo<insightDays),previous=demoProductOrders.filter(o=>o.daysAgo>=insightDays&&o.daysAgo<insightDays*2);const people=demoAudience.filter(p=>current.some(o=>o.customer===p.id));const grouped=(key,arr=people)=>Object.entries(arr.reduce((a,p)=>(a[p[key]]=(a[p[key]]||0)+1,a),{})).sort((a,b)=>b[1]-a[1]);const products=['Brown butter cookies','Weekend pastry box','Signature sourdough'].map(name=>({name,current:current.filter(o=>o.product===name).reduce((s,o)=>s+o.units,0),previous:previous.filter(o=>o.product===name).reduce((s,o)=>s+o.units,0)})).sort((a,b)=>b.current-a.current);return {people,current,previous,genders:grouped('gender'),ages:grouped('age'),preferences:grouped('preference'),products}}
function bars(items,total){return `<div class="insight-bars">${items.map(([label,n],i)=>`<div><div><span>${esc(label)}</span><strong>${total?Math.round(n/total*100):0}% <small>(${n})</small></strong></div><div class="bar-track"><span style="width:${total?n/total*100:0}%;background:${['#2d6650','#83a777','#bdd49e','#ddcdb1'][i%4]}"></span></div></div>`).join('')}</div>`}
function insights(){const a=analyticsData(),top=a.products[0],women=a.genders.find(x=>x[0]==='Women')?.[1]||0;return heading('Get to know your kind of people.','A clearer picture of who visits, what they love, and what to try next.')+`<div class="insight-disclaimer"><span class="pill">SYNTHETIC DEMO DATA</span><p>Sample cohort of ${a.people.length} customers · Example period ending 29 Sep 2026. Demographics are fictional and are never inferred from names or photos.</p><select id="insight-period" aria-label="Analytics period"><option value="30" ${insightDays===30?'selected':''}>Last 30 days</option><option value="7" ${insightDays===7?'selected':''}>Last 7 days</option></select></div><div class="stats">${stat('Customers in this period',a.people.length,'Synthetic sample')}${stat('Women in sample',Math.round(women/a.people.length*100)+'%','Voluntarily shared · demo')}${stat('Most common age',a.ages[0]?.[0]||'—','Sample audience')}${stat('Orders in period',a.current.length,'Sample order history')}</div><div class="grid2"><section class="panel"><div class="eyebrow">WHO’S FINDING YOU</div><h2>Gender distribution</h2>${bars(a.genders,a.people.length)}</section><section class="panel"><div class="eyebrow">LIFE STAGES, LITTLE PASSIONS</div><h2>Age ranges</h2>${bars(a.ages,a.people.length)}</section><section class="panel"><div class="eyebrow">WHAT SPARKS THEIR CURIOSITY</div><h2>Customer preferences</h2>${bars(a.preferences,a.people.length)}<p class="subtle">Preferences are self-selected in this synthetic dataset.</p></section><section class="panel"><div class="eyebrow">WHAT’S GETTING THE MOST LOVE</div><h2>Popular products</h2>${a.products.map((p,i)=>`<div class="product-ranking"><span>0${i+1}</span><div><strong>${p.name}</strong><p>${p.current} units · ${p.previous} in previous ${insightDays} days</p></div><b>${p.previous?Math.round((p.current-p.previous)/p.previous*100):0}%</b></div>`).join('')}</section></div><section class="trend-panel"><div><span class="eyebrow">A PATTERN WORTH TESTING</span><h2>${top.name} leads this period.</h2><p>It accounts for ${Math.round(top.current/a.products.reduce((s,p)=>s+p.current,0)*100)}% of sample units sold. Try featuring it at the top of your menu, then compare the next period.</p></div><div><span class="pill">A suggestion, not a forecast</span><p>A small sample can change quickly. Test a limited batch before increasing production.</p><button class="btn secondary" data-new="ask-insight">Discuss with Grove</button></div></section>`}
function orderForm(){return `<form id="order-v2"><div class="order-form-grid"><div class="field"><label for="order-customer">Customer</label><input id="order-customer" name="customer" placeholder="Customer name" required></div><div class="field"><label for="order-product">Product</label><select id="order-product" name="product">${state.business.menu.map((m,i)=>`<option value="${i}">${esc(m[0])} · ${money(m[1])}</option>`).join('')}</select></div><div class="field"><label for="order-quantity">Quantity</label><input id="order-quantity" type="number" min="1" max="100" value="1" name="quantity" required></div><button class="btn">Record demo order</button></div></form>`}
dashboard=function(){const t=totals('2026-09');return heading('A little overview. A lot of possibility.','Welcome to '+esc(state.business.name)+'.','<a href="#/owner/editor" class="btn secondary">Edit storefront</a>')+`<div class="stats">${stat('Page visits','1,284','September · sample')}${stat('Customers',state.customers.length,'Your community')}${stat('Paid income',money(t.income),'September 2026')}${stat('Chain referrals','38','September · sample')}</div><section class="orders-panel panel"><div class="section-title" style="margin-top:0"><div><div class="eyebrow">YOUR COUNTER, WITHOUT THE CLUTTER</div><h2>In-store demo orders</h2></div><span class="pill">${state.orders.length} recorded</span></div>${orderForm()}${state.orders.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Order</th><th>Total</th><th>Date</th></tr></thead><tbody>${state.orders.slice().reverse().slice(0,5).map(o=>`<tr><td>${esc(o.customer)}</td><td>${o.quantity} × ${esc(o.product)}</td><td>${money(o.total)}</td><td>${date(o.date)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Record a sample sale to update finances and customer visits together.</p>'}</section><div class="grid2" style="margin-top:24px"><section class="panel"><div class="section-title" style="margin-top:0"><h2>The business picture</h2><a href="#/owner/finance" class="text-btn">View finances</a></div>${chart()}<div class="legend"><span>Income</span><span>Expenses</span></div></section><section class="owner-feature"><span class="eyebrow">KNOW WHAT BRINGS THEM BACK</span><h2>A little insight.<br>A smarter next step.</h2><p>See your audience, their interests, and the products getting the most love.</p><a class="btn soft" href="#/owner/insights">Explore customer insights</a>${mascot('owner-feature-mascot')}</section></div>`};
editor=function(){return originalPages.editor().replaceAll('type="number" min="0" step="0.01"','type="text" inputmode="decimal" pattern="[0-9]+(\\.[0-9]{1,2})?"').replace('background:'+esc(state.business.accent),'background:#2d6650')};
function businessPage(){if(!state.isBusiness)return heading('Your passion has a place here.','Join The Grove as a business and create your own discovery point.')+`<div class="grid2"><form class="panel" id="business-signup"><div class="eyebrow">BUSINESS & QR</div><h2>Let’s grow your business.</h2>${field('Business name','name',state.business.name)}${field('Business contact email','email',state.business.email,'email')}${field('Business phone number','phone',state.business.phone,'tel')}<div class="field"><label for="business-description">Tell us about your business</label><textarea id="business-description" name="description" required>${esc(state.business.description)}</textarea></div><label class="consent-line"><input type="checkbox" required> I understand this creates a local demo business profile.</label><button class="btn full">Create business profile</button></form><div class="registration-story">${mascot('registration-mascot')}<h2>Small business.<br>Big possibilities.</h2><p>Your storefront, customer insights, and a QR code for your counter—all in your business studio.</p></div></div>`;return heading('A little scan. A new connection.','Your business profile and customer entry point.')+`<div class="qr-layout"><section class="panel"><div class="eyebrow">BUSINESS & QR</div><h2>${esc(state.business.name)}</h2><p>${esc(state.business.description)}</p><p class="muted">${esc(state.business.email)}<br>${esc(state.business.phone)}</p><a class="btn secondary" href="#/owner/editor">Manage storefront</a></section><section class="panel qr-panel"><h2>Your business QR</h2><div id="business-qr" aria-label="QR code linking to the customer storefront"></div><p class="subtle">${location.hostname==='127.0.0.1'||location.hostname==='localhost'?'Local preview: this code works on this computer only. A published address is needed for customers’ phones.':'Opens your customer storefront.'}</p><div class="modal-actions"><button class="btn secondary small" data-new="copy-store-link">Copy storefront link</button><button class="btn small" data-new="store-preview">Preview</button></div></section></div><section class="panel" style="margin-top:24px"><h2>From the first scan</h2><p class="muted">Customers open your storefront, explore the menu, and confirm a demo visit to start their chain.</p></section><section class="panel orders-panel" style="margin-top:24px"><h2>In-store demo orders</h2>${orderForm()}</section>`}
function renderQR(){const box=$('#business-qr');if(!box)return;const link=`${location.origin}${location.pathname}#/customer/store/1`;if(window.qrcode){const q=qrcode(0,'M');q.addData(link);q.make();box.innerHTML=q.createSvgTag({cellSize:5,margin:12,scalable:true})}else box.innerHTML=`<p>QR unavailable. <a href="${link}">Open storefront</a></p>`}
function answerQuestion(q){const lower=q.toLowerCase(),entry=state.knowledge.find(k=>k.question.toLowerCase()===lower)||state.knowledge.find(k=>{const words=k.question.toLowerCase().split(/\W+/).filter(w=>w.length>3);return words.filter(w=>lower.includes(w)).length>=2});if(entry)return {text:entry.answer,source:'Your knowledge board'};if(/gender|women|woman|men|age|demographic|audience|customers|customer insight/.test(lower)){const a=analyticsData();return {text:`In the synthetic ${insightDays}-day sample, ${a.people.length} customers placed orders. ${Math.round((a.genders.find(x=>x[0]==='Women')?.[1]||0)/a.people.length*100)}% are women and the largest age group is ${a.ages[0][0]}. These are fictional, voluntarily shared demographics—not inferences about real customers.`,source:'Synthetic customer analytics'}}if(/popular|product|trend|sell|insight/.test(lower)){const a=analyticsData(),p=a.products[0];return {text:`${p.name} is the leading product in this ${insightDays}-day sample, with ${p.current} units versus ${p.previous} in the previous period. You could test it as a featured menu item. This is a sample-data suggestion, not a demand forecast.`,source:'Synthetic product orders'}}if(/income|profit|finance|revenue|expense|payment/.test(lower)){const t=totals();return {text:`For ${financeMonth}, recorded paid income is ${money(t.income)}, expenses are ${money(t.expense)}, and profit is ${money(t.profit)}. ${money(t.pending)} is awaiting payment. These numbers come from your editable demo finance records.`,source:'Your demo finance records'}}if(/reward|chain|cashback|discount/.test(lower))return {text:'The first visit starts a chain at full price. Every next different business gives exactly $1 off. Four stops can save $3 in total. There is no 2% cashback or increasing per-stop discount.',source:'The Grove reward rules'};if(/appointment|booking|schedule|calendar/.test(lower)){const a=state.appointments.filter(a=>a.status==='Confirmed'&&(a.businessId||1)===1);return {text:`There are ${a.length} confirmed demo appointments for your business. Open Calendar to add appointments or update reminder preferences. No actual reminders are sent from this prototype.`,source:'Your demo calendar'}}return {text:'I don’t have an answer for that yet. I can explain your sample customer insights, popular products, finances, appointments, and chain rewards. Add your business-specific question and answer to the knowledge board, then ask again.',source:'No matching knowledge entry'}}
function assistantPage(){return heading('A little help from Grove.','Ask about your business, or teach your demo assistant something new.')+`<div class="assistant-layout"><section class="panel chat-panel"><div class="chat-heading">${mascot('chat-avatar')}<div><h2>Ask Grove</h2><span class="muted">Demo assistant · uses records and your knowledge board</span></div><button class="text-btn" data-new="clear-chat">Clear chat</button></div><div class="suggested-questions">${['Who are my customers?','Which products are popular?','How is my profit?'].map(q=>`<button class="chip" data-new="ask" data-question="${q}">${q}</button>`).join('')}</div><div id="chat-messages" class="chat-messages" aria-live="polite">${state.chats.length?state.chats.map(m=>`<div class="chat-message ${m.role}"><span>${m.role==='user'?'YOU':'GROVE'}</span><p>${esc(m.text)}</p>${m.source?`<small>${esc(m.source)}</small>`:''}</div>`).join(''):'<div class="chat-welcome"><h3>Hi, I’m Grove.</h3><p>Let’s turn a question into your next little step.</p></div>'}</div><form id="chat-form"><label class="sr-only" for="chat-query">Ask a question</label><input id="chat-query" name="query" placeholder="What would you like to know?" required maxlength="600"><button class="btn" aria-label="Send question">Send</button></form><p class="subtle">No AI service connected. Answers come from local rules and your saved demo data.</p></section><section class="panel knowledge-panel"><div class="eyebrow">YOUR BUSINESS, IN YOUR WORDS</div><h2>Knowledge board</h2><p class="muted">Add questions and answers for Grove to use. Entries stay in this browser.</p><form id="knowledge-form">${field('Question','question')}<div class="field"><label for="knowledge-answer">Answer</label><textarea id="knowledge-answer" name="answer" required maxlength="3000"></textarea></div><button class="btn">Add to knowledge</button></form><div class="knowledge-list">${state.knowledge.map(k=>`<details><summary>${esc(k.question)}</summary><p>${esc(k.answer)}</p><button class="text-btn" data-new="delete-knowledge" data-id="${k.id}">Remove entry</button></details>`).join('')}</div><button class="btn secondary full" data-new="export-knowledge">Export dataset (JSON)</button></section></div>`}
function sendChat(question){const text=question.trim();if(!text)return;state.chats.push({role:'user',text});state.chats.push({role:'assistant',...answerQuestion(text)});persist();renderPage();const box=$('#chat-messages');if(box)box.scrollTop=box.scrollHeight}
renderPage=function(){if(leafMap){leafMap.remove();leafMap=null}const pages={home,discover,chain,profile,settings,store:storePage,dashboard,editor,customers,insights,finance,calendar,business:businessPage,assistant:assistantPage,history};$('#content').innerHTML=(pages[route]||home)();if(route==='discover')initMap();if(route==='business')renderQR();if(route==='assistant'&&$('#chat-messages'))$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight};
const storyScenes=[['Hi, I’m Grove.','A small sprout with one big belief: good things grow together.'],['Start with a little curiosity.','Find the people making wonderful things around you.'],['One discovery leads to another.','Your first visit starts a chain. Every next different business gives $1 off.'],['Let’s grow something good.','More local love. More real connections. Your next favourite is waiting.']];
function storyFrame(){const s=storyScenes[storyIndex];$('#modal').innerHTML=`<button class="modal-close" data-action="close" aria-label="Close story">${icon('close')}</button><div class="story-screen"><span class="eyebrow">THE GROVE · A LITTLE STORY</span>${mascot('scene-'+storyIndex)}<h2>${s[0]}</h2><p>${s[1]}</p><div class="story-progress">${storyScenes.map((_,i)=>`<button class="${i===storyIndex?'active':''}" data-new="story-scene" data-index="${i}" aria-label="Story scene ${i+1}" aria-current="${i===storyIndex}"></button>`).join('')}</div><div class="story-controls"><button class="btn secondary small" data-new="story-pause">${storyTimer?'Pause':'Play'}</button><button class="btn small" data-new="story-next">${storyIndex===3?'Watch again':'Next scene'}</button></div></div>`}
function playStory(){clearInterval(storyTimer);storyTimer=setInterval(()=>{storyIndex++;if(storyIndex>=3){storyIndex=3;clearInterval(storyTimer);storyTimer=null}storyFrame()},5000)}
function startStory(){storyIndex=0;showModal('');if(state.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)playStory();storyFrame()}
$('#modal').addEventListener('close',()=>{clearInterval(storyTimer);storyTimer=null});
document.addEventListener('click',e=>{const anchor=e.target.closest('[data-section]');if(anchor){e.preventDefault();document.getElementById(anchor.dataset.section)?.scrollIntoView({behavior:state.motion?'smooth':'auto'});return}const cat=e.target.closest('[data-discover-category]');if(cat){category=cat.dataset.discoverCategory;savedOnly=false;region='All'}const el=e.target.closest('[data-new]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const action=el.dataset.new,id=Number(el.dataset.id);if(action==='story')startStory();else if(action==='story-next'){storyIndex=(storyIndex+1)%4;storyFrame()}else if(action==='story-scene'){storyIndex=Number(el.dataset.index);storyFrame()}else if(action==='story-pause'){if(storyTimer){clearInterval(storyTimer);storyTimer=null}else playStory();storyFrame()}else if(action==='motion'){state.motion=!state.motion;persist();document.body.classList.toggle('motion-paused',!state.motion);document.querySelectorAll('[data-new="motion"]').forEach(b=>{b.textContent=state.motion?'Ⅱ Pause motion':'▶ Play motion';b.setAttribute('aria-pressed',state.motion)});toast(state.motion?'Motion enabled':'Motion paused')}else if(action==='signup-interest'){const value=el.dataset.value;signupDraft.interests=signupDraft.interests.includes(value)?signupDraft.interests.filter(c=>c!==value):[...signupDraft.interests,value];shell()}else if(action==='signup-back'){authStep=0;shell()}else if(action==='open-store'){selectedBusinessId=id;location.hash=`/customer/store/${id}`}else if(action==='confirm-visit')confirmVisit(id);else if(action==='store-preview')previewStore();else if(action==='locate')locateUser();else if(action==='map-reset'){mapCenter=[1.347,103.839];mapZoom=11;region='All';renderPage()}else if(action==='focus-pin'){leafMap?.setView(coordinates[id],14);leafMap?.eachLayer(layer=>{if(layer.getLatLng&&layer.getLatLng().lat===coordinates[id][0]&&layer.openPopup)layer.openPopup()})}else if(action==='search-area'){const list=filtered().filter(b=>leafMap?.getBounds().contains(coordinates[b.id]));$('#map-results').innerHTML=mapResults(list);$('#map-result-count').textContent=`${list.length} ${list.length===1?'discovery':'discoveries'} in this area`;toast('Map area updated')}else if(action==='copy-store-link'){const link=`${location.origin}${location.pathname}#/customer/store/1`;navigator.clipboard?.writeText(link).then(()=>toast('Storefront link copied')).catch(()=>showModal(`<div class="modal-body"><h2>Your storefront link</h2><input readonly value="${esc(link)}" aria-label="Storefront link"></div>`))}else if(action==='clear-chat'){state.chats=[];persist();renderPage();toast('A fresh conversation is ready')}else if(action==='ask')sendChat(el.dataset.question);else if(action==='ask-insight'){location.hash='/owner/assistant';setTimeout(()=>sendChat('Which products are popular?'),50)}else if(action==='delete-knowledge'){state.knowledge=state.knowledge.filter(k=>k.id!==id);persist();renderPage();toast('Knowledge entry removed')}else if(action==='export-knowledge'){downloadFile('grove-knowledge.json',JSON.stringify({version:1,entries:state.knowledge},null,2),'application/json')}} ,true);
document.addEventListener('submit',e=>{const f=e.target;if(!['login-v2','signup-details','signup-finish','settings-v2','business-signup','chat-form','knowledge-form','order-v2'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));if(f.id==='login-v2'){state.profile.email=d.email;persist();location.hash='/customer/home';toast('Welcome to your Grove');return}if(f.id==='signup-details'){signupDraft={...signupDraft,...d};authStep=1;shell();return}if(f.id==='signup-finish'){if(!signupDraft.interests.length){toast('Choose at least one interest.');return}state.profile={...state.profile,...signupDraft,...d};persist();authStep=0;category='All';savedOnly=false;region='All';location.hash='/customer/home';toast('Your Grove is ready. Welcome!');celebrate();return}if(f.id==='settings-v2'){state.profile={...state.profile,...d};persist();shell();toast('Your changes are saved');return}if(f.id==='business-signup'){state.business={...state.business,...d};state.isBusiness=true;persist();shell();toast('Your business profile is ready');celebrate();return}if(f.id==='chat-form'){sendChat(d.query);return}if(f.id==='knowledge-form'){state.knowledge.push({id:Date.now(),question:d.question.trim(),answer:d.answer.trim()});persist();renderPage();toast('Grove has a new answer to use');return}if(f.id==='order-v2'){const product=state.business.menu[Number(d.product)],quantity=Number(d.quantity);if(!product||quantity<1||!Number.isInteger(quantity)){toast('Enter a valid order quantity.');return}const today=localDate(),total=quantity*Number(product[1]);state.orders.push({id:Date.now(),customer:d.customer,product:product[0],quantity,total,date:today});state.transactions.push({date:today,description:`${quantity} × ${product[0]} · ${d.customer}`,type:'Income',amount:total,status:'Paid'});const customer=state.customers.find(c=>c.name.toLowerCase()===d.customer.toLowerCase());if(customer){customer.visits++;customer.last=today}else state.customers.push({name:d.customer,phone:'Not provided',email:'Not provided',visits:1,first:today,last:today,next:null});persist();renderPage();toast('Order recorded · finances and customer visits updated');celebrate()}} ,true);
document.addEventListener('change',e=>{if(e.target.id==='insight-period'){insightDays=Number(e.target.value);renderPage()}if(e.target.id==='motion-setting'){state.motion=e.target.checked;persist();document.body.classList.toggle('motion-paused',!state.motion);toast('Motion preference saved')}});
function downloadFile(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Dataset downloaded')}
